350	func (r *Registry) checkIssue(req IssueRequest) error {
351		op, ok := r.state.Accounts[req.Operator]
352		if !ok {
353			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
354		}
355		if !op.Active {
356			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
357		}
358		s, ok := r.state.Series[req.SeriesID]
359		if !ok {
360			return fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
361		}
362		if s.Sealed {
363			return fmt.Errorf("%w: 系列 %s", ErrSeriesSealed, req.SeriesID)
364		}
365		if s.CreatorID != req.Operator {
366			return fmt.Errorf("%w: 只有系列创建账户 %s 可以发行", ErrForbidden, s.CreatorID)
367		}
368		if _, ok := r.state.Items[req.ItemID]; ok {
369			return fmt.Errorf("%w: 藏品编号 %s 已被使用", ErrAlreadyExists, req.ItemID)
370		}
371		h, ok := r.state.Accounts[req.HolderID]
372		if !ok {
373			return fmt.Errorf("%w: 初始持有人账户 %s", ErrNotFound, req.HolderID)
374		}
375		if !h.Active {
376			return fmt.Errorf("%w: 初始持有人账户 %s", ErrAccountInactive, req.HolderID)
377		}
378		return nil
379	}
