881	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
882		if prev.Kind != "auth_revoke" || prev.Params != sig {
883			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
884				ErrRequestConflict, prev.Operator, prev.RequestID)
885		}
886		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
887		if prev.Rejected {
888			res.Err = codeErr(prev.Reason)
889			res.Status = ""
890			return res, res.Err
891		}
892		return res, nil
893	}
