895	func proxyTransferParamsSig(req ProxyTransferRequest) string {
896		b, _ := json.Marshal(struct {
897			Kind   string `json:"kind"`
898			AuthID string `json:"auth_id"`
899			Reason string `json:"reason"`
900		}{"proxy_transfer", req.AuthID, req.Reason})
901		return string(b)
902	}
903	
904	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
905	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
906	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
907	// 操作者记为实际受托账户并可通过授权编号追溯。
908	//
909	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
910	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
911	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
912	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
913	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
914	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
915	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
916		missing := []string{}
917		if strings.TrimSpace(req.Operator) == "" {
918			missing = append(missing, "operator")
919		}
920		if strings.TrimSpace(req.Reason) == "" {
921			missing = append(missing, "reason")
922		}
923		if strings.TrimSpace(req.RequestID) == "" {
924			missing = append(missing, "request_id")
925		}
926		if strings.TrimSpace(req.AuthID) == "" {
927			missing = append(missing, "auth_id")
928		}
929		if len(missing) > 0 {
930			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
931				ErrInvalidArgument, strings.Join(missing, ", "))
932		}
933		r.mu.Lock()
934		defer r.mu.Unlock()
935		if err := r.checkOpen(); err != nil {
936			return ProxyTransferResult{}, err
937		}
938	
939		now := r.now()
940		key := requestKey(req.Operator, req.RequestID)
941		sig := proxyTransferParamsSig(req)
942		if prev, ok := r.state.Requests[key]; ok {
943			return r.replayProxyTransfer(prev, sig)
944		}
945	
946		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
947			if !isValidationErr(bizErr) {
948				r.state.Requests[key] = request{
949					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
950					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
951				}
952				_ = r.commit()
953			}
954			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
955		}
956	
957		a := r.state.Authzs[req.AuthID]
958		h := r.state.Holdings[a.ItemID]
959		seq := r.state.NextSeq + 1
960		r.state.NextSeq = seq
961		from := h.OwnerID
962		fromVer := h.Version
963		h.OwnerID = a.ToID
964		h.Version = fromVer + 1
965		r.state.Holdings[a.ItemID] = h
966		r.state.History = append(r.state.History, historyEntry{
967			Seq: seq, Kind: "transfer", ItemID: a.ItemID, Operator: req.Operator,
968			Reason: req.Reason, RequestID: req.RequestID,
969			FromID: from, ToID: a.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
970			AuthID: a.ID,
971		})
972		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
973		// 人（授权人），不记给受托人。应付明细与持有、历史、授权使用状态
974		// 在同一临界区内一次落盘。
975		it := r.state.Items[a.ItemID]
976		royalty := newRoyaltyRec(seq, a.ItemID, it.SeriesID, a.Price,
977			r.state.Series[it.SeriesID].Royalty, from)
978		r.state.Royalties[seq] = royalty
979		a.Status = "used"
980		a.UsedTxSeq = seq
981		a.UsedAt = now
982		r.state.Authzs[a.ID] = a
983		authSeq := r.state.NextAuthSeq + 1
984		r.state.NextAuthSeq = authSeq
985		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
986			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
987			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
988			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: seq, OccurredAt: now,
989		})
990		r.state.Requests[key] = request{
991			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
992			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: from, ToID: a.ToID,
993			Version: fromVer + 1, TxSeq: seq,
994		}
995		if err := r.commit(); err != nil {
996			return ProxyTransferResult{}, err
997		}
998		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: from,
999			ToID: a.ToID, Version: fromVer + 1, TxSeq: seq,
1000			Price: royalty.Price, Payables: publicPayables(royalty.Payees),
1001			Remainder: royalty.Remainder}, nil
1002	}
1003	
1004	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1005		a, ok := r.state.Authzs[req.AuthID]
1006		if !ok {
1007			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1008		}
1009		op, ok := r.state.Accounts[req.Operator]
1010		if !ok {
1011			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1012		}
1013		granter, gOk := r.state.Accounts[a.GranterID]
1014		to, tOk := r.state.Accounts[a.ToID]
1015		if req.Operator != a.TrusteeID {
1016			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1017				ErrForbidden, req.Operator, req.AuthID)
1018		}
1019		if !gOk {
1020			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1021		}
1022		if !tOk {
1023			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1024		}
1025		if !op.Active {
1026			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1027		}
1028		if !granter.Active {
1029			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1030		}
1031		if !to.Active {
1032			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1033		}
1034		switch authzCurrentStatus(a, now) {
1035		case AuthRevoked:
1036			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1037		case AuthExpired:
1038			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1039		case AuthUsed:
1040			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1041		}
1042		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1043		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1044		h, ok := r.state.Holdings[a.ItemID]
1045		if !ok {
1046			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1047		}
1048		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1049			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1050				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1051		}
1052		return nil
1053	}
1054	
1055	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1056		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1057			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1058				ErrRequestConflict, prev.Operator, prev.RequestID)
1059		}
1060		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1061			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1062		if prev.Rejected {
1063			res.Err = codeErr(prev.Reason)
1064			return res, res.Err
1065		}
1066		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1067		// 原价款与应付明细，不重复计入。
1068		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1069		return res, nil
1070	}
