1074	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1075	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1076	// 到期但尚未终结的授权返回 AuthExpired。
1077	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1078		r.mu.Lock()
1079		defer r.mu.Unlock()
1080		if err := r.checkOpen(); err != nil {
1081			return Authorization{}, err
1082		}
1083		a, ok := r.state.Authzs[authID]
1084		if !ok {
1085			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1086		}
1087		return Authorization{
1088			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1089			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1090			Status:    authzCurrentStatus(a, r.now()),
1091			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1092			RevokedAt: a.RevokedAt,
1093		}, nil
1094	}
