1096	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1097	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1098	// 不存在时返回包裹 ErrNotFound 的错误。
1099	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1100		r.mu.Lock()
1101		defer r.mu.Unlock()
1102		if err := r.checkOpen(); err != nil {
1103			return nil, err
1104		}
1105		if _, ok := r.state.Items[itemID]; !ok {
1106			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1107		}
1108		out := make([]AuthorizationEvent, 0)
1109		for _, e := range r.state.AuthEvents {
1110			if e.ItemID != itemID {
1111				continue
1112			}
1113			out = append(out, AuthorizationEvent{
1114				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1115				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1116				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1117				OccurredAt: e.OccurredAt,
1118			})
1119		}
1120		return out, nil
1121	}
