1125	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1126	func (r *Registry) GetItem(id string) (Item, error) {
1127		r.mu.Lock()
1128		defer r.mu.Unlock()
1129		if err := r.checkOpen(); err != nil {
1130			return Item{}, err
1131		}
1132		it, ok := r.state.Items[id]
1133		if !ok {
1134			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1135		}
1136		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1137			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1138	}
1139	
1140	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1141	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1142		r.mu.Lock()
1143		defer r.mu.Unlock()
1144		if err := r.checkOpen(); err != nil {
1145			return Holding{}, err
1146		}
1147		h, ok := r.state.Holdings[itemID]
1148		if !ok {
1149			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1150		}
1151		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1152	}
1153	
1154	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1155	// ErrNotFound 的错误；停用账户仍可正常查询。
1156	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1157		r.mu.Lock()
1158		defer r.mu.Unlock()
1159		if err := r.checkOpen(); err != nil {
1160			return nil, err
1161		}
1162		if _, ok := r.state.Accounts[accountID]; !ok {
1163			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1164		}
1165		out := make([]Holding, 0)
1166		for _, h := range r.state.Holdings {
1167			if h.OwnerID == accountID {
1168				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1169			}
1170		}
1171		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1172		return out, nil
1173	}
1174	
1175	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1176	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1177	// 返回包裹 ErrNotFound 的错误。
1178	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1179		r.mu.Lock()
1180		defer r.mu.Unlock()
1181		if err := r.checkOpen(); err != nil {
1182			return nil, err
1183		}
1184		if _, ok := r.state.Items[itemID]; !ok {
1185			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1186		}
1187		out := make([]HistoryEntry, 0)
1188		for _, e := range r.state.History {
1189			if e.ItemID != itemID {
1190				continue
1191			}
1192			out = append(out, HistoryEntry{
1193				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1194				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1195				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1196			})
1197		}
1198		return out, nil
1199	}
1200	
1201	// ---- 幂等辅助 ----
1202	
1203	func requestKey(operator, requestID string) string {
1204		return operator + "\x00" + requestID
1205	}
1206	
1207	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1208	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1209	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1210	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1211	// 并回放。
1212	func isValidationErr(err error) bool {
1213		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1214	}
1215	
1216	var errCodes = map[error]string{
1217		ErrNotFound:             "not_found",
1218		ErrAlreadyExists:        "already_exists",
1219		ErrAccountInactive:      "account_inactive",
1220		ErrSeriesSealed:         "series_sealed",
1221		ErrConflict:             "conflict",
1222		ErrSameAccount:          "same_account",
1223		ErrForbidden:            "forbidden",
1224		ErrAuthorizationRevoked: "authorization_revoked",
1225		ErrAuthorizationExpired: "authorization_expired",
1226		ErrAuthorizationUsed:    "authorization_used",
1227		ErrRoyaltyFrozen:        "royalty_frozen",
1228	}
1229	
1230	var codeErrs = map[string]error{
1231		"not_found":             ErrNotFound,
1232		"already_exists":        ErrAlreadyExists,
1233		"account_inactive":      ErrAccountInactive,
1234		"series_sealed":         ErrSeriesSealed,
1235		"conflict":              ErrConflict,
1236		"same_account":          ErrSameAccount,
1237		"forbidden":             ErrForbidden,
1238		"authorization_revoked": ErrAuthorizationRevoked,
1239		"authorization_expired": ErrAuthorizationExpired,
1240		"authorization_used":    ErrAuthorizationUsed,
1241		"royalty_frozen":        ErrRoyaltyFrozen,
1242	}
1243	
1244	func errCode(err error) string {
1245		for sentinel, code := range errCodes {
1246			if errors.Is(err, sentinel) {
1247				return code
1248			}
1249		}
1250		return "rejected"
1251	}
1252	
1253	func codeErr(code string) error {
1254		if e, ok := codeErrs[code]; ok {
1255			return e
1256		}
1257		return errors.New("registry: 请求曾被拒绝")
1258	}
